import {
  BidictKeyError,
  BidictValueDuplicationError,
  createBidictFromLiteralPairs,
} from './lib/bidict/index.mjs';

function writeLine(value) {
  process.stdout.write(`${String(value)}\n`);
}

function writeExit(result) {
  const stream = result.stream === 'stderr' ? process.stderr : process.stdout;
  stream.write(result.text);
  process.exitCode = result.code;
}

function main() {
  const scriptName = getScriptName(process.argv[1]);
  const parsed = parseTest19Args(process.argv.slice(2), scriptName);

  if (parsed.kind === 'exit') {
    writeExit(parsed);
    return;
  }

  const { k1, v1, k2, v2 } = parsed.values;

  const b1 = createBidictFromLiteralPairs([
    [k1, v1],
    [k2, v2],
  ]);
  const b2 = b1.copy();
  writeLine(b2);

  b1.set('new', 999n);
  writeLine(b1);
  writeLine(b2);

  const result = b2.inv[v1];
  writeLine(result);
}

