    return toHexEscape(character);
  }

  return character;
}

export function formatPythonString(value) {
  const quote = chooseQuote(value);
  const escapedValue = Array.from(value, (character) => escapeCharacter(character, quote)).join('');
  return `${quote}${escapedValue}${quote}`;
}

export function formatPythonValue(value) {
  if (typeof value === 'string') {
    return formatPythonString(value);
  }

  return String(value);
}

export function formatPythonDict(entries) {
  const parts = entries.map(([key, value]) => `${formatPythonString(key)}: ${formatPythonValue(value)}`);
  return `{${parts.join(', ')}}`;
}
